258	/**
259	 * 初始化家庭系统
260	 */
261	function initFamilySystem(state) {
262	  if (!state.family) {
263	    state.family = {
264	      relationship: null,
265	      spouse: null,
266	      children: [],
267	      parents: {
268	        father: { age: 55, health: "healthy", name: "父亲" },
269	        mother: { age: 53, health: "healthy", name: "母亲" },
270	      },
271	      expenses: {
272	        monthlyMortgage: 0,
273	        monthlyLiving: 3000,
274	        monthlyChildren: 0,
275	        monthlyParents: 0,
276	      },
277	      events: [],
278	    };
279	  }
280	}
281	
282	/**
283	 * 寻找约会对象
284	 */
285	function findDatingTarget(state, location) {
286	  const locations = {
287	    workplace: { pool: "同事", probability: 0.3 },
288	    social: { pool: "社交活动", probability: 0.4 },
289	    online: { pool: "社交软件", probability: 0.5 },
290	    friend_intro: { pool: "朋友介绍", probability: 0.6 },
291	    random: { pool: "偶遇", probability: 0.2 },
292	  };
293	
294	  const loc = locations[location] || locations.random;
295	
296	  if (Math.random() > loc.probability) {
297	    StateManager.addMessage(`在${loc.pool}没有遇到合适的人...`, "hint");
298	    return null;
299	  }
300	
301	  const names = [
302	    "小雅",
303	    "小晴",
304	    "小雯",
305	    "小琳",
306	    "小婷",
307	    "小慧",
308	    "小蕾",
309	    "小琪",
310	    "小欣",
311	    "小怡",
312	    "小萱",
313	    "小颖",
314	    "小菲",
315	    "小静",
316	    "小美",
317	    "小丽",
318	    "小娜",
319	    "小燕",
320	    "小萍",
321	    "小芳",
322	  ];
323	  const partnerTypeKeys = Object.keys(SPOUSE_TYPES);
324	  const typeKey =
325	    partnerTypeKeys[Math.floor(Math.random() * partnerTypeKeys.length)];
326	  const partnerType = SPOUSE_TYPES[typeKey];
327	  const name = names[Math.floor(Math.random() * names.length)];
328	
329	  const target = {
330	    id:
331	      "target_" +
332	      state.player.day +
333	      "_" +
334	      Math.random().toString(36).substr(2, 9),
335	    name: name,
336	    type: typeKey,
337	    typeData: partnerType,
338	    relationship: 20, // 初始认识
339	    stage: "acquaintance",
340	    lastInteraction: state.player.day,
341	    favoriteActivities: ["cafe_chat", "movie_date", "park_walk"],
342	  };
343	
344	  state.family.datingTarget = target;
345	  StateManager.addMessage(
346	    `💕 在${loc.pool}认识了${name}（${partnerType.name}型）`,
347	    "success",
348	  );
349	
350	  return target;
351	}
352	
353	/**
354	 * 进行约会
355	 */
356	function goDating(state, eventId) {
357	  const target = state.family.datingTarget;
358	  if (!target) {
359	    return { success: false, message: "还没有约会对象" };
360	  }
361	
362	  const event = DATING_EVENTS[eventId];
363	  if (!event) {
364	    return { success: false, message: "不存在的约会事件" };
365	  }
366	
367	  // 检查阶段是否允许
368	  const stageOrder = [
369	    "acquaintance",
370	    "friend",
371	    "good_friend",
372	    "crush",
373	    "dating",
374	    "engaged",
375	    "married",
376	  ];
377	  const allowedStages = {
378	    first_meal: ["acquaintance", "friend", "good_friend"],
379	    movie_date: ["friend", "good_friend", "crush", "dating"],
380	    park_walk: ["friend", "good_friend", "crush", "dating"],
381	    cafe_chat: ["acquaintance", "friend", "good_friend", "crush", "dating"],
382	    trip: ["good_friend", "crush", "dating"],
383	    meet_parents: ["dating"],
384	    confession: ["crush"],
385	  };
386	
387	  if (!allowedStages[eventId].includes(target.stage)) {
388	    return { success: false, message: `当前关系阶段还不适合${event.name}` };
389	  }
390	
391	  // 检查费用
392	  const cost =
393	    event.cost[0] + Math.floor(Math.random() * (event.cost[1] - event.cost[0]));
394	  if (state.resources.cash < cost) {
395	    return { success: false, message: `现金不足，需要¥${cost}` };
396	  }
397	
398	  state.resources.cash -= cost;
399	
400	  // 计算成功率（基础成功率 + 关系加成）
401	  const relationshipBonus = (target.relationship / 100) * 0.3;
402	  const successChance = Math.min(0.95, event.successChance + relationshipBonus);
403	
404	  if (Math.random() < successChance) {
405	    // 成功
406	    target.relationship = Math.min(
407	      100,
408	      target.relationship + event.relationshipGain,
409	    );
410	    target.lastInteraction = state.player.day;
411	
412	    // 检查阶段升级
413	    checkRelationshipStage(target);
414	
415	    StateManager.addMessage(
416	      `✅ ${event.icon} ${event.name}很成功！关系+${event.relationshipGain}`,
417	      "success",
418	    );
419	
420	    // 检查是否进入下一阶段
421	    if (eventId === "confession" && target.relationship >= 85) {
422	      target.stage = "dating";
423	      StateManager.addMessage(`💑 你和${target.name}正式在一起了！`, "success");
424	    }
425	
426	    return {
427	      success: true,
428	      relationship: target.relationship,
429	      stage: target.stage,
430	    };
431	  } else {
432	    // 失败
433	    target.relationship = Math.max(0, target.relationship - 5);
434	    StateManager.addMessage(
435	      `❌ ${event.icon} ${event.name}不太顺利...关系-5`,
436	      "warning",
437	    );
438	    return { success: false, relationship: target.relationship };
439	  }
440	}
441	
442	/**
443	 * 检查关系阶段升级
444	 */
445	function checkRelationshipStage(target) {
446	  const oldStage = target.stage;
447	
448	  if (target.relationship >= 100) target.stage = "married";
449	  else if (target.relationship >= 95) target.stage = "engaged";
450	  else if (target.relationship >= 85) target.stage = "dating";
451	  else if (target.relationship >= 75) target.stage = "crush";
452	  else if (target.relationship >= 60) target.stage = "good_friend";
453	  else if (target.relationship >= 40) target.stage = "friend";
454	  else if (target.relationship >= 20) target.stage = "acquaintance";
455	  else target.stage = "stranger";
456	
457	  if (oldStage !== target.stage) {
458	    const stageData = RELATIONSHIP_STAGES[target.stage];
459	    StateManager.addMessage(`💕 关系升级为「${stageData.name}」！`, "success");
460	  }
461	}
462	
463	/**
464	 * 结婚
465	 */
466	function getMarried(state) {
467	  const target = state.family.datingTarget;
468	  if (!target || target.stage !== "engaged") {
469	    return { success: false, message: "需要先订婚" };
470	  }
471	
472	  const weddingCost = 50000 + Math.floor(Math.random() * 100000);
473	  if (state.resources.cash < weddingCost) {
474	    return { success: false, message: `婚礼需要¥${weddingCost}，现金不足` };
475	  }
476	
477	  state.resources.cash -= weddingCost;
478	
479	  state.family.spouse = {
480	    name: target.name,
481	    type: target.type,
482	    typeData: target.typeData,
483	    age: 25 + Math.floor(Math.random() * 5),
484	    income: target.typeData.income,
485	    relationship: 100,
486	    children: [],
487	    happiness: 80,
488	  };
489	
490	  state.family.datingTarget = null;
491	  state.family.relationship = null;
492	
493	  StateManager.addMessage(`💒 你和${target.name}结婚了！`, "success");
494	
495	  // 更新家庭支出
496	  state.family.expenses.monthlyLiving += 2000; // 婚后生活成本增加
497	
498	  return { success: true };
499	}
500	
501	/**
502	 * 生育子女
503	 */
504	function haveChild(state) {
505	  const spouse = state.family.spouse;
506	  if (!spouse) {
507	    return { success: false, message: "需要先结婚" };
508	  }
509	
510	  const birthCost = 5000 + Math.floor(Math.random() * 10000);
511	  if (state.resources.cash < birthCost) {
512	    return { success: false, message: `生育需要¥${birthCost}，现金不足` };
513	  }
514	
515	  state.resources.cash -= birthCost;
516	
517	  const names = [
518	    "宝宝",
519	    "小宝贝",
520	    "小天使",
521	    "小星星",
522	    "小阳光",
523	    "小花朵",
524	    "小可爱",
525	    "小宝贝",
526	  ];
527	  const genders = ["男", "女"];
528	  const gender = genders[Math.floor(Math.random() * genders.length)];
529	  const name = names[Math.floor(Math.random() * names.length)];
530	
531	  const child = {
532	    id:
533	      "child_" +
534	      state.player.day +
535	      "_" +
536	      Math.random().toString(36).substr(2, 9),
537	    name: name,
538	    gender: gender,
539	    birthDay: state.player.day,
540	    age: 0,
541	    stage: "infant",
542	    intelligence: 50 + Math.floor(Math.random() * 30),
543	    personality: ["活泼", "安静", "内向", "外向", "敏感", "乐观"][
544	      Math.floor(Math.random() * 6)
545	    ],
546	    happiness: 80,
547	    health: 90,
548	    educationLevel: 0,
549	    interests: [],
550	  };
551	
552	  state.family.children.push(child);
553	  spouse.children.push(child.id);
554	
555	  // 更新家庭支出
556	  updateChildExpenses(state);
557	
558	  StateManager.addMessage(
559	    `👶 你有了${gender === "男" ? "儿子" : "女儿"}${name}！`,
560	    "success",
561	  );
562	
563	  return { success: true, child: child };
564	}
565	
566	/**
567	 * 更新子女支出
568	 */
569	function updateChildExpenses(state) {
570	  let monthlyTotal = 0;
571	
572	  for (const child of state.family.children) {
573	    const stage = getChildStage(child.age);
574	    if (stage) {
575	      monthlyTotal += getStageMonthlyCost(stage);
576	    }
577	  }
578	
579	  state.family.expenses.monthlyChildren = monthlyTotal;
580	}
581	
582	/**
583	 * 获取子女阶段
584	 */
585	function getChildStage(age) {
586	  for (const [key, stage] of Object.entries(CHILD_STAGES)) {
587	    if (age >= stage.age[0] && age <= stage.age[1]) {
588	      return key;
589	    }
590	  }
591	  return "adult";
592	}
593	
594	/**
595	 * 获取阶段月花费
596	 */
597	function getStageMonthlyCost(stageKey) {
598	  const costs = {
599	    infant: 2000,
600	    toddler: 1500,
601	    primary: 1000,
602	    middle: 2000,
603	    high: 3000,
604	    university: 4000,
605	    adult: 0,
606	  };
607	  return costs[stageKey] || 0;
608	}
609	
610	/**
611	 * 每日家庭更新
612	 */
613	function tickFamilyDaily(state) {
614	  const day = state.player.day;
615	  const family = state.family;
616	
617	  if (!family) return;
618	
619	  // 更新子女年龄
620	  for (const child of family.children) {
621	    const oldAge = child.age;
622	    child.age = (day - child.birthDay) / 365;
623	
624	    if (oldAge < 1 && child.age >= 1) {
625	      StateManager.addMessage(`🎂 ${child.name}满1岁了！`, "event");
626	    }
627	
628	    // 更新阶段
629	    const stageKey = getChildStage(Math.floor(child.age));
630	    if (stageKey !== child.stage) {
631	      child.stage = stageKey;
632	      const stage = CHILD_STAGES[stageKey];
633	      StateManager.addMessage(
634	        `📚 ${child.name}进入${stage.name}阶段（${stage.education}）`,
635	        "info",
636	      );
637	    }
638	
639	    // 随机成长事件
640	    if (Math.random() < 0.05) {
641	      child.intelligence = Math.min(100, child.intelligence + 1);
642	      StateManager.addMessage(`📈 ${child.name}又聪明了一点（智力+1）`, "hint");
643	    }
644	  }
645	
646	  // 更新父母健康
647	  if (family.parents) {
648	    const parents = family.parents;
649	
650	    // 父母年龄增长
651	    parents.father.age++;
652	    parents.mother.age++;
653	
654	    // 根据年龄更新健康状态
655	    updateParentHealth(parents.father);
656	    updateParentHealth(parents.mother);
657	
658	    // 随机健康事件
659	    if (Math.random() < 0.02) {
660	      const parentKey = Math.random() < 0.5 ? "father" : "mother";
661	      const parent = parents[parentKey];
662	      StateManager.addMessage(
663	        `⚠️ ${parent.name}身体不太舒服，需要关注`,
664	        "warning",
665	      );
666	    }
667	  }
668	
669	  // 更新配偶关系
670	  if (family.spouse) {
671	    const spouse = family.spouse;
672	
673	    // 自然衰减（不互动的情况下）
674	    if (day - spouse.lastInteraction > 7) {
675	      spouse.relationship = Math.max(0, spouse.relationship - 1);
676	    }
677	
678	    // 月度收入
679	    state.resources.cash += spouse.income;
680	    state.resources.totalEarned += spouse.income;
681	  }
682	
683	  // 月度家庭支出
684	  if (day % 30 === 0) {
685	    const expenses = family.expenses;
686	    const totalMonthly =
687	      expenses.monthlyMortgage +
688	      expenses.monthlyLiving +
689	      expenses.monthlyChildren +
690	      expenses.monthlyParents;
691	
692	    if (state.resources.cash >= totalMonthly) {
693	      state.resources.cash -= totalMonthly;
694	      StateManager.addMessage(
695	        `📊 本月家庭支出¥${totalMonthly.toLocaleString()}`,
696	        "hint",
697	      );
698	    } else {
699	      StateManager.addMessage(
700	        `⚠️ 家庭支出¥${totalMonthly.toLocaleString()}，现金不足！`,
701	        "warning",
702	      );
703	    }
704	  }
705	}
706	
707	/**
708	 * 更新父母健康状态
709	 */
710	function updateParentHealth(parent) {
711	  const age = parent.age;
712	
713	  if (age < 55) {
714	    parent.health = "healthy";
715	  } else if (age < 65) {
716	    parent.health = Math.random() < 0.3 ? "minor_illness" : "healthy";
717	  } else if (age < 75) {
718	    const rand = Math.random();
719	    if (rand < 0.3) parent.health = "healthy";
720	    else if (rand < 0.7) parent.health = "chronic_illness";
721	    else parent.health = "serious_illness";
722	  } else {
723	    const rand = Math.random();
724	    if (rand < 0.2) parent.health = "chronic_illness";
725	    else if (rand < 0.6) parent.health = "serious_illness";
726	    else parent.health = "critical";
727	  }
728	}
729	
730	/**
731	 * 陪伴父母
732	 */
733	function accompanyParents(state, parentKey) {
734	  const parents = state.family.parents;
735	  const parent = parents[parentKey];
736	  if (!parent) return { success: false, message: "父母信息不存在" };
737	
738	  const AP_COST = 15;
739	  if (state.player.actionPoints < AP_COST) {
740	    return { success: false, message: "行动力不足" };
741	  }
742	
743	  state.player.actionPoints -= AP_COST;
744	
745	  const healthState = PARENT_HEALTH_STATES[parent.health];
746	  parent.companionshipDays = (parent.companionshipDays || 0) + 1;
747	
748	  StateManager.addMessage(
749	    `👨‍👦 陪伴${parent.name}，${healthState.name}状态，需要更多关心`,
750	    "info",
751	  );
752	
753	  return { success: true };
754	}
755	
756	/**
757	 * 带父母看病
758	 */
759	function takeParentToHospital(state, parentKey) {
760	  const parents = state.family.parents;
761	  const parent = parents[parentKey];
762	  if (!parent) return { success: false, message: "父母信息不存在" };
763	
764	  const healthState = PARENT_HEALTH_STATES[parent.health];
765	  const cost = healthState.medicalCost;
766	
767	  if (state.resources.cash < cost) {
768	    return {
769	      success: false,
770	      message: `治疗需要¥${cost.toLocaleString()}，现金不足`,
771	    };
772	  }
773	
774	  state.resources.cash -= cost;
775	
776	  // 治疗成功，健康改善
777	  const healthOrder = [
778	    "healthy",
779	    "minor_illness",
780	    "chronic_illness",
781	    "serious_illness",
782	    "critical",
783	  ];
784	  const currentIndex = healthOrder.indexOf(parent.health);
785	  if (currentIndex > 0) {
786	    parent.health = healthOrder[currentIndex - 1];
787	    StateManager.addMessage(
788	      `🏥 带${parent.name}看病，健康从${healthState.name}改善到${PARENT_HEALTH_STATES[parent.health].name}`,
789	      "success",
790	    );
791	  } else {
792	    StateManager.addMessage(
793	      `✅ ${parent.name}身体健康，定期检查很有必要`,
794	      "hint",
795	    );
796	  }
797	
798	  return { success: true };
799	}
800	
801	/**
802	 * 设置房贷
803	 */
804	function setMortgage(state, monthlyPayment) {
805	  state.family.expenses.monthlyMortgage = monthlyPayment;
806	  StateManager.addMessage(
807	    `🏠 房贷设置为每月¥${monthlyPayment.toLocaleString()}`,
808	    "info",
809	  );
810	  return { success: true };
811	}
812	
813	/**
814	 * 家庭活动
815	 */
816	const FAMILY_ACTIVITIES = {
817	  family_dinner: {
818	    name: "家庭聚餐",
819	    icon: "🍲",
820	    cost: [200, 500],
821	    apCost: 20,
822	    happinessGain: 10,
823	    desc: "一家人一起吃顿好的",
824	  },
825	  park_outing: {
826	    name: "公园游玩",
827	    icon: "🌳",
828	    cost: [50, 150],
829	    apCost: 15,
830	    happinessGain: 8,
831	    desc: "带家人去公园散步游玩",
832	  },
833	  movie_night: {
834	    name: "家庭电影夜",
835	    icon: "🎬",
836	    cost: [100, 200],
837	    apCost: 10,
838	    happinessGain: 6,
839	    desc: "一起看部电影",
840	  },
841	  travel: {
842	    name: "家庭旅行",
843	    icon: "✈️",
844	    cost: [3000, 10000],
845	    apCost: 50,
846	    happinessGain: 25,
847	    desc: "带家人出去旅行",
848	  },
849	  home_renovate: {
850	    name: "家居改造",
851	    icon: "🔨",
852	    cost: [5000, 20000],
853	    apCost: 30,
854	    happinessGain: 15,
855	    desc: "装修房子，提升居住品质",
856	  },
857	};
858	
859	function doFamilyActivity(state, activityId) {
860	  const activity = FAMILY_ACTIVITIES[activityId];
861	  if (!activity) return { success: false, message: "不存在的家庭活动" };
862	
863	  // 检查行动力
864	  if (state.player.actionPoints < activity.apCost) {
865	    return { success: false, message: `需要${activity.apCost}点行动力` };
866	  }
867	
868	  // 检查费用
869	  const cost =
870	    activity.cost[0] +
871	    Math.floor(Math.random() * (activity.cost[1] - activity.cost[0]));
872	  if (state.resources.cash < cost) {
873	    return { success: false, message: `需要¥${cost}，现金不足` };
874	  }
875	
876	  state.player.actionPoints -= activity.apCost;
877	  state.resources.cash -= cost;
878	
879	  // 应用效果
880	  if (state.family.spouse) {
881	    state.family.spouse.happiness = Math.min(
882	      100,
883	      (state.family.spouse.happiness || 80) + activity.happinessGain,
884	    );
885	  }
886	
887	  for (const child of state.family.children) {
888	    child.happiness = Math.min(100, child.happiness + activity.happinessGain);
889	  }
890	
891	  StateManager.addMessage(
892	    `👨‍👩‍👧‍👦 ${activity.icon} ${activity.name}！家人很开心`,
893	    "success",
894	  );
895	
896	  return { success: true };
897	}
898	
899	/**
900	 * 获取家庭摘要
901	 */
902	function getFamilySummary(state) {
903	  const family = state.family;
904	  if (!family) return null;
905	
906	  const summary = {
907	    hasSpouse: !!family.spouse,
908	    spouseName: family.spouse?.name || null,
909	    childCount: family.children.length,
910	    parentsAlive: 0,
911	    parentsHealthy: 0,
912	    monthlyExpenses: 0,
913	  };
914	
915	  if (family.parents) {
916	    for (const key of ["father", "mother"]) {
917	      const parent = family.parents[key];
918	      if (parent.age < 100) {
919	        summary.parentsAlive++;
920	        if (parent.health === "healthy") summary.parentsHealthy++;
921	      }
922	    }
923	  }
924	
925	  summary.monthlyExpenses =
926	    family.expenses.monthlyMortgage +
927	    family.expenses.monthlyLiving +
928	    family.expenses.monthlyChildren +
929	    family.expenses.monthlyParents;
930	
931	  return summary;
932	}
933	
934	/**
935	 * 百科注册
936	 */
937	if (typeof window !== "undefined") {
938	  window.MECHANICS = window.MECHANICS || {};
939	  window.MECHANICS.family_life = {
940	    id: "family_life",
941	    name: "家庭与生活",
942	    icon: "👨‍👩‍👧",
