944	    version: "1.0.0",
945	    related: ["mechanics:main", "mechanics:critical_needs"],
946	    sections: [
947	      {
948	        kind: "desc",
949	        text: "人生不只是奋斗，还有家人。家庭系统让你体验从单身到结婚、从二人世界到三口之家的完整人生旅程。",
950	      },
951	      {
952	        kind: "subhead",
953	        text: "💕 关系发展阶段",
954	      },
955	      {
956	        kind: "list",
957	        items: [
958	          "❓ 陌生人 → 👋 认识 → 🙂 朋友 → 👫 好朋友 → 💕 暧昧 → 💑 恋爱 → 💍 订婚 → 💒 结婚",
959	        ],
960	      },
961	      {
962	        kind: "subhead",
963	        text: "👶 子女成长阶段",
964	      },
965	      {
966	        kind: "list",
967	        items: [
968	          "👶 婴儿（0-2岁）：奶粉、尿布、陪伴",
969	          "🧒 幼儿（3-5岁）：幼儿园、玩具、绘本",
970	          "📚 小学生（6-11岁）：学费、课外班",
971	          "📖 初中生（12-14岁）：补习班、青春期",
